22	    <button data-testid="job-submit" type="submit">Submit job</button>
23	    <div data-testid="form-error" role="alert"></div>
24	  </form>
25	  <h2>Jobs</h2>
26	  <ul data-testid="job-list"></ul>
27	  <script>
28	    const form = document.querySelector('[data-testid="job-form"]');
29	    const alertRegion = document.querySelector('[data-testid="form-error"]');
30	    const list = document.querySelector('[data-testid="job-list"]');
31	    function showError(data) {
32	      const err = data && data.error;
33	      alertRegion.textContent = err ? [err.message, ...(err.fields || []).map(f => `${f.field}: ${f.message}`)].join(' ') : 'Request failed.';
34	    }
35	    function render(jobs) {
36	      list.replaceChildren(...jobs.map(job => {
37	        const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
38	        const title = document.createElement('strong'); title.textContent = job.input;
39	        const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
40	        const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
41	        const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.error || '');
42	        const meta = document.createElement('div'); meta.className = 'meta'; meta.append('Status: ', status, ' · Progress: ', progress);
43	        item.append(title, meta, result); return item;
44	      }));
45	    }
46	    async function refresh() {
47	      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch {}
48	    }
49	    form.addEventListener('submit', async event => {
50	      event.preventDefault(); alertRegion.textContent = '';
51	      const data = new FormData(form);
52	      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
53	      try {
54	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
55	        const body = await response.json();
56	        if (!response.ok) showError(body); else { form.elements.input.value = ''; await refresh(); }
57	      } catch { alertRegion.textContent = 'Unable to submit job.'; }
58	    });
59	    refresh(); setInterval(refresh, 500);
60	  </script>
61	</body>
62	</html>
